    public static function key(string $source):string{return 'manager_'.substr(hash('sha256',$source),0,24);}
    public static function baseMessages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];
        foreach(self::ENGLISH+FreeListMessages::ENGLISH+ControlMessages::ENGLISH+CalendarMessages::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;
        return $messages;
    }
